{
  "findings": [
    {
      "check_id": "CKV2_AWS_41",
      "title": "EC2 instances have no IAM role attached",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "The EC2 instances do not specify an IAM instance profile, preventing workloads from using scoped, temporary AWS credentials through an attached role."
    },
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance assigned a public IP address",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "The conditional expression assigns a public IP address to the instance at count index 1, increasing its exposure to public networks."
    },
    {
      "check_id": "AVD-AWS-0028",
      "title": "EC2 instances do not require IMDSv2 tokens",
      "resource": "aws_instance.ubuntu",
      "severity": "HIGH",
      "explanation": "No metadata options require session tokens, so the instances may permit unauthenticated IMDSv1 requests and be more vulnerable to metadata credential theft."
    }
  ],
  "patched_code": "resource "aws_iam_role" "ubuntu" {
  name_prefix = "ubuntu-ec2-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ubuntu" {
  name_prefix = "ubuntu-ec2-"
  role        = aws_iam_role.ubuntu.name
}

resource "aws_instance" "ubuntu" {
  count                       = 3
  ami                         = data.aws_ami.ubuntu_14_04.image_id
  instance_type               = "t2.micro"
  associate_public_ip_address = false
  subnet_id                   = aws_subnet.my_subnet.id
  iam_instance_profile        = aws_iam_instance_profile.ubuntu.name

  metadata_options {
    http_tokens = "required"
  }
}
",
  "fix_summary": "Disabled public IP assignment, required IMDSv2 tokens, and attached a minimally privileged EC2 IAM role through an instance profile. The role has no permissions policies and only permits EC2 to assume it."
}
